style.css:
@-moz-document domain("youtube.com") {
/* 1. Set a custom background image for the whole page */
    /* You can change the URL below to any image you want to see behind the glass */
    html, body, ytd-app {
        background-image: url('https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=2564&auto=format&fit=crop') !important; 
        background-size: cover !important;
        background-attachment: fixed !important;
        background-color: transparent !important;
    }

    /* 2. Override YouTube's default solid background colors */
    html[dark], [dark] {
        --yt-spec-base-background: transparent !important;
        --yt-spec-raised-background: rgba(20, 20, 20, 0.4) !important;
        --yt-spec-menu-background: rgba(20, 20, 20, 0.6) !important;
        --yt-spec-general-background-a: transparent !important;
        --yt-spec-general-background-b: transparent !important;
        --yt-spec-general-background-c: transparent !important;
    }

    /* 3. Apply the "Liquid Glass" effect to top bar, sidebar, and menus */
    #masthead-container,
    #guide-wrapper,
    #guide-inner-content,
    ytd-mini-guide-renderer,
    .ytp-popup,
    ytd-multi-page-menu-renderer,
    tp-yt-paper-dialog {
        background: rgba(25, 25, 25, 0.4) !important; /* Semi-transparent dark background */
        backdrop-filter: blur(15px) !important;       /* The liquid blur effect */
        -webkit-backdrop-filter: blur(15px) !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important; /* Faint white edge like real glass */
        box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.3) !important;
    }

    /* 4. Make the search box match the glass theme */
    ytd-searchbox[has-focus] #container.ytd-searchbox,
    #container.ytd-searchbox {
        background: rgba(255, 255, 255, 0.1) !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
        box-shadow: inset 0 0 5px rgba(0,0,0,0.2) !important;
    }
    
    /* 5. Make search button transparent */
    #search-icon-legacy.ytd-searchbox {
        background: transparent !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
    }

    /* 6. Clean up video cards and main viewing areas to let the background show */
    ytd-rich-item-renderer, 
    ytd-video-renderer, 
    ytd-compact-video-renderer,
    #columns {
        background-color: transparent !important;
    }
}
